"""One-time source materialization for authenticated browser setup.
No network, API keys, or package installs. Never overwrites an existing source tree.
The complete source is committed by the first successful Pages workflow.
"""
import base64
import io
from pathlib import Path
import zipfile

ROOT = Path(__file__).resolve().parent
PAYLOAD = ""

if not (ROOT / "src/main.py").exists():
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))) as archive:
        for entry in archive.infolist():
            target = (ROOT / entry.filename).resolve()
            if ROOT not in target.parents or ".git" in Path(entry.filename).parts or ".github" in Path(entry.filename).parts:
                raise ValueError("Invalid bootstrap archive path")
            if target.exists():
                raise ValueError("Refusing to overwrite existing files")
        archive.extractall(ROOT)
    print("Materialized original source and initial articles")
else:
    print("Source already present; bootstrap skipped")
